import{z as i,x as n,o as E,c as p,q as l,j as A,D as e,d as o,s as r,S as t}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"移动 NPU 工具链","description":"","frontmatter":{"title":"移动 NPU 工具链","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/edge-npu-toolchain.md","filePath":"llm/edge-npu-toolchain.md","lastUpdated":1791413859000}'),s={name:"llm/edge-npu-toolchain.md"};function d(P,a,N,h,m,C){const B=n("Mermaid");return E(),p("div",null,[a[2]||(a[2]=l('<h1 id="移动-npu-工具链" tabindex="-1">移动 NPU 工具链 <a class="header-anchor" href="#移动-npu-工具链" aria-label="Permalink to &quot;移动 NPU 工具链&quot;">​</a></h1><div class="epigraph"><p>NPU 的性能不在芯片里，在编译器里：内存规划在编译期一次做完，动态 shape 是它唯一的天敌。</p><footer>—— 据高通 QNN、MediaTek NeuroPilot、Apple Core ML 与 OpenVINO 官方文档口径整理</footer></div><p><a href="/llm/edge-hardware-spectrum">上一课</a>把端侧硬件排进「容量、带宽、算力、精度、功耗」的坐标系，并指出 NPU 的 TOPS 只有在模型真正编译进 NPU 之后才存在。缺口正是这一步：把一张 LLM 计算图变成 NPU 上可执行的产物，中间隔着图导入、量化转换、分图与内存规划几道工序。本课写工具链怎么走完这些工序、LLM 的动态 shape 卡在哪、以及分图边界的隐性成本。后课的量化实践以本课的「后端吃什么格式」为输入。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NPU 不是通用处理器，而是数据流加速器：片上缓冲怎么分、算子怎么排程，都在编译期定死。通用流程五步：模型导出（ONNX 或框架 trace）、图优化（算子融合、布局变换）、量化转换、分图（把图切成 NPU/CPU/GPU 三段，即 delegate 模式）、逐后端生成与打包。<span class="marginnote">delegate（分图）模式可以翻译成「分包施工」：整栋楼（模型）的主体工程包给 NPU 这支专业施工队，它干不了的零活（不支持的算子）转包给 CPU。转包交接的次数越多，来回搬运就越贵，所以选型期就要数清楚有几个转包点。</span>每步都有检查单：算子覆盖表决定哪些算子 fallback 到 CPU（哪些算子天然对 NPU 友好，<a href="/llm/npu-friendly-ops">NPU 友好算子</a>已经分过类）；量化格式决定后面整条链（下一课展开）；内存规划报告给出峰值缓冲，超了就得砍上下文或批大小。</p><p>LLM 的特殊困难是自回归：序列长度每步加一，KV 随之增长，而 NPU 编译期要静态 shape。三条出路：序列长度分桶，pad 到档位，用浪费的算力换静态；prefill 与 decode 分工——prefill 形状虽长但一次性、可静态编译，decode 循环留 CPU/GPU，这是<a href="/llm/mobile-npu-deploy">移动端 NPU 部署</a>的主流结论；或改用支持动态 shape 的新一代运行时。选哪条不是品味问题，取决于这条产品最看重首 token 还是每个 token。</p>',6)),(E(),A(t,null,{default:e(()=>[r(B,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%A8%A1%E5%9E%8B%E5%AF%BC%E5%87%BA%20ONNX%22%5D%20--%3E%20O%5B%22%E5%9B%BE%E4%BC%98%E5%8C%96%E4%B8%8E%E7%AE%97%E5%AD%90%E6%94%B9%E5%86%99%22%5D%0A%20%20O%20--%3E%20Q%5B%22%E9%87%8F%E5%8C%96%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20Q%20--%3E%20P%7B%22%E7%AE%97%E5%AD%90%E5%85%A8%E8%A6%86%E7%9B%96%3F%22%7D%0A%20%20P%20--%3E%7C%E5%90%A6%7C%20FB%5B%22%E7%BC%BA%E5%8F%A3%E7%AE%97%E5%AD%90%20fallback%20CPU%22%5D%0A%20%20P%20--%3E%7C%E6%98%AF%7C%20S%5B%22%E5%88%86%E5%9B%BE%E4%B8%8E%E5%86%85%E5%AD%98%E8%A7%84%E5%88%92%22%5D%0A%20%20FB%20--%3E%20S%0A%20%20S%20--%3E%20N%5B%22NPU%20%E4%BA%A7%E7%89%A9%22%5D%0A%20%20S%20--%3E%20C%5B%22CPU%2FGPU%20%E4%BA%A7%E7%89%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工具按硬件阵营对号：Hexagon 用 QNN，天玑用 NeuroPilot，Apple 用 Core ML 配 <a href="/llm/mlx-apple">Apple MLX</a>，PC 端 NPU 用 <a href="/llm/openvino">OpenVINO</a>，瑞芯微用 RKNN。选型期查三件事：目标模型在该工具链上的算子覆盖率；量化粒度与格式的支持程度，per-channel 与 group-wise 的支持差异极大；KV 与动态 shape 的官方方案是什么。集成后再查一件：逐段计时。端到端延迟会掩盖分图边界的成本——每跨一次 NPU/CPU 边界，激活要拷贝一次，精度常要转换一次，热路径上多来几次，NPU 省下的时间就全吐回去了。<span class="marginnote">算一笔具体的账：一次跨界要搬 2048×4096 的 fp16 激活，就是 \\(2048 \\times 4096 \\times 2\\) 字节 \\(=16\\) MB；按 50 GB/s 的内存带宽算要约 0.3 ms，热路径跨四次边界光搬运就近 1.3 ms——这段时间常常已超过 NPU 本身省下来的计算时间。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么动态 shape 是天敌：tiling 大小、片上缓冲与 DMA 排程都是编译期常数，序列长度一变成符号量，这些就得推迟到运行时，而 NPU 恰恰靠编译期的确定性吃饭。所以工程上「静态化」无处不在：上下文上限、长度分桶、KV 留在 CPU 内存而 NPU 只消费定长窗口。这些决定一旦写进产品，比如上下文上限四千，动它就要连内存预算一起动。fallback 链同理：它不是异常路径，是常态路径，每个 fallback 点都要有计时与精度核对，否则性能与质量会一起悄悄漏走。</p>',4)),(E(),A(t,null,{default:e(()=>[r(B,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%E7%94%9F%E6%88%90%3A%20%E5%BA%8F%E5%88%97%E9%95%BF%E5%BA%A6%E6%AF%8F%E6%AD%A5%20%2B1%22%5D%20--%3E%20Q%7B%22%E9%80%89%E5%93%AA%E6%9D%A1%E9%9D%99%E6%80%81%E5%8C%96%E5%87%BA%E8%B7%AF%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%88%86%E6%A1%B6%22%7C%20B1%5B%22pad%20%E5%88%B0%E5%9B%BA%E5%AE%9A%E6%A1%A3%E4%BD%8D%22%5D%0A%20%20Q%20--%3E%7C%22%E5%88%86%E5%B7%A5%22%7C%20B2%5B%22prefill%20%E9%9D%99%E6%80%81%E7%BC%96%E8%AF%91%E8%BF%9B%20NPU%3Cbr%2F%3Edecode%20%E7%95%99%20CPU%2FGPU%22%5D%0A%20%20Q%20--%3E%7C%22%E6%8D%A2%E8%BF%90%E8%A1%8C%E6%97%B6%22%7C%20B3%5B%22%E5%8A%A8%E6%80%81%20shape%20%E6%96%B0%E8%BF%90%E8%A1%8C%E6%97%B6%22%5D%0A%20%20B1%20--%3E%20R1%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E6%B5%AA%E8%B4%B9%E7%9A%84%E7%AE%97%E5%8A%9B%E4%B8%8E%20pad%20%E6%97%B6%E9%97%B4%22%5D%0A%20%20B2%20--%3E%20R2%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E4%B8%A4%E6%AC%A1%E5%88%86%E5%9B%BE%E8%BE%B9%E7%95%8C%22%5D%0A%20%20B3%20--%3E%20R3%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E4%BE%9D%E8%B5%96%E5%B7%A5%E5%85%B7%E9%93%BE%E6%88%90%E7%86%9F%E5%BA%A6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p><span class="marginnote">分图边界是最大的隐性成本：一次跨界等于一次内存拷贝加一次精度转换，fp16 与 int8 缓冲来回变换，足以让「算子在 NPU 上更快」变成「端到端更慢」。覆盖表要在选型期查，不是集成后期补。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评各家工具链的版本与跑分，那类数字半年一换；OpenVINO 与 MLX 的推理细节在各自课里，本课只借它们讲阵营差异。量化格式与校准的具体做法是下一课的主题。数值一致性问题——同一份权重在 NPU 与 CPU 上输出不完全一致——留到端侧评测课统一处理。<span class="marginnote">初学者容易以为「两边输出不一样」是出了 bug。实际上只要量化格式、算子融合方式或求和顺序不同，同一份权重在 NPU 与 CPU 上输出就必然有小数点后几位的差异，这是正常现象，关键看偏差是否在评测容差之内，而不是要求逐位相同。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NPU 工具链五步：导出、图优化、量化转换、分图、逐后端生成，每步一张检查单。</li><li>LLM 的动态 shape 靠分桶、prefill 与 decode 分工、或动态运行时化解。</li><li>分图边界有拷贝与精度转换成本，逐段计时是唯一可靠的验收方式。</li><li>算子覆盖与量化格式支持在选型期查；fallback 是常态路径而非异常。</li><li>出处：据 QNN、NeuroPilot、Core ML、OpenVINO、RKNN 官方文档口径整理；执行单元分工见本站移动端 NPU 部署课。</li></ul>',5))])}const D=i(s,[["render",d]]);export{c as __pageData,D as default};
